import re

from moler.exceptions import CommandFailure, ParsingDone

from ta_moler.cmd.hub.rfswcli.generichub import GenericHub


class AntStatus(GenericHub):
    """AntStatus command class."""

    def __init__(self, connection, port, prompt=None, newline_chars=None, runner=None):
        """
        Get Ant Status.

        :param connection: moler connection to device, terminal when command is executed
        :param port: antenna port.
        :param prompt: Prompt of the starting shell
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(AntStatus, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.port = port
        # The output is a 3 level structure, need the following 3 variable for parse
        self._cur_top_level = ""
        self._cur_second_level = ""
        self._cur_level = ""

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        return f"ant_status {self.port}"

    def on_new_line(self, line, is_full_line):
        """
        Execute all parsing methods.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._command_error(line)
                self._parse_useless_line(line)
                self._parse_top_level_key_value(line)
                self._parse_top_level_parent(line)
                self._parse_second_level_parent(line)
                self._parse_key_value(line)
            except ParsingDone:
                pass
        return super(AntStatus, self).on_new_line(line, is_full_line)

    # Error! St13runtime_error: Invalid port!
    _re_error = re.compile(r"Error!\s*(?P<CMD_ERROR>.*)$")

    def _command_error(self, line):
        if self._regex_helper.search_compiled(AntStatus._re_error, line):
            self.set_exception(CommandFailure(self, self._regex_helper.group("CMD_ERROR")))
            raise ParsingDone

    def _parse_useless_line(self, line):
        line = line.strip()
        if not line or line.startswith("/"):
            raise ParsingDone

    # 2, subVersion = 0x00000005
    _re_top_level_key_val = re.compile(r"\d+\,\s*(?P<KEY>\S+)\s*=\s*(?P<VALUE>\S+)", re.I)

    def _parse_top_level_key_value(self, line):
        # found a top level key/value pair
        line = line.strip()
        if self._regex_helper.match_compiled(AntStatus._re_top_level_key_val, line):
            self.current_ret[self._regex_helper.group("KEY")] = self._regex_helper.group("VALUE")
            self._cur_top_level = self._regex_helper.group("KEY")
            self._cur_second_level = ""
            raise ParsingDone

    # 3, EID info
    _re_top_level_parent = re.compile(r"\d+\,\s*(?P<KEY>.+)", re.I)

    def _parse_top_level_parent(self, line):
        # found a top level parent line
        line = line.strip()
        if self._regex_helper.match_compiled(AntStatus._re_top_level_parent, line):
            self._cur_top_level = self._regex_helper.group("KEY")
            self._cur_second_level = ""
            self.current_ret[self._cur_top_level] = {}
            raise ParsingDone

    # board-identity {
    _re_second_level_parent = re.compile(r"(?P<KEY>\S+)\s*\{", re.I)

    def _parse_second_level_parent(self, line):
        # found 2nd level parent line
        line = line.strip()
        if self._regex_helper.match_compiled(AntStatus._re_second_level_parent, line):
            self._cur_second_level = self._regex_helper.group("KEY")
            self.current_ret[self._cur_top_level][self._cur_second_level] = {}
            raise ParsingDone

    # production-code = "474979A.103";
    _re_key_val = re.compile(r"(?P<KEY>.+)\s*[:=]\s*(?P<VALUE>.+)", re.I)

    def _parse_key_value(self, line):
        # found a key/value pair
        line = line.strip()
        if self._regex_helper.match_compiled(AntStatus._re_key_val, line):
            key = self._regex_helper.group("KEY")
            val = str(self._regex_helper.group("VALUE").rstrip(";").strip('"'))
            if self._cur_second_level:
                self.current_ret[self._cur_top_level][self._cur_second_level][key] = val
            else:
                self.current_ret[self._cur_top_level][key] = val
            raise ParsingDone


